// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }

    function testFuzz_property(uint256 firstAmount, uint256 secondAmount, address actor) public {
        vm.assume(firstAmount <= VALUE_CAP);
        vm.assume(secondAmount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(firstAmount <= 1000 ether && secondAmount <= 1000 ether);

        vm.deal(actor, firstAmount + secondAmount);

        vm.startPrank(actor);
        c.Put{value: firstAmount}(0);
        c.Put{value: secondAmount}(0);
        vm.stopPrank();

        (uint256 unlockTime, uint256 balance) = c.Acc(actor);
        unlockTime; // observed via getter; assertion reads balance
        assertTrue(balance == firstAmount + secondAmount, "deposits must accumulate");
    }
}
